import { useEffect, useState } from "react";
import { useSearchParams, Link } from "react-router-dom";
import { api } from "../lib/api";
import LoadingSpinner from "../components/LoadingSpinner";
import { ArrowRight, Search, Music, Disc3, Album } from "lucide-react";

export default function SearchPage() {
  const [params] = useSearchParams();
  const q = params.get("q") || "";
  const [r, setR] = useState({ tracks: [], albums: [], artists: [], lore: [] });
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!q) return;
    setLoading(true);
    api.get(`/search?q=${encodeURIComponent(q)}`)
      .then((res) => setR(res.data))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [q]);

  const totalResults = r.tracks.length + r.albums.length + r.artists.length + r.lore.length;

  const Section = ({ title, items, render, icon: Icon }) => items.length > 0 && (
    <section className="mt-10">
      <div className="flex items-center gap-2 mb-4">
        {Icon && <Icon size={16} />}
        <div className="meta-ink">{title} · {items.length}</div>
      </div>
      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">{items.map(render)}</div>
    </section>
  );

  return (
    <div className="max-w-[1480px] mx-auto px-6 py-12">
      <div className="meta-ink mb-2">search</div>
      <div className="flex items-end gap-4 flex-wrap">
        <h1 className="font-display font-black text-5xl tracking-tighter">"{q}"</h1>
        {!loading && q && <span className="meta-ink mb-2">{totalResults} result{totalResults !== 1 ? 's' : ''}</span>}
      </div>

      {loading && (
        <div className="mt-10 text-center meta-ink">
          <LoadingSpinner size={20} />
          <div className="mt-2">searching the archive…</div>
        </div>
      )}

      {!loading && q && (
        <>
          {/* Quick suggestion for empty results */}
          {totalResults === 0 && (
            <div className="mt-10 brutal-card-static p-8 text-center">
              <Search size={32} className="mx-auto mb-3" />
              <p className="font-editorial italic text-xl">no results for "{q}".</p>
              <p className="meta-ink mt-2">try an artist, album, track, or lore keyword. searches are typo-tolerant.</p>
            </div>
          )}

          <Section title="albums" items={r.albums} icon={Album}
            render={(a) => (
              <Link key={a.id} to={`/album/${a.id}`} className="brutal-card p-5 flex items-start gap-4 group">
                <div className="w-12 h-12 flex-shrink-0 border-2 border-[var(--ink)]" style={{ background: a.color || 'var(--parchment-deep)' }} />
                <div className="flex-1 min-w-0">
                  <div className="meta-ink">album</div>
                  <div className="font-display font-bold text-xl truncate">{a.title}</div>
                  {a.artist_name && <div className="font-editorial italic text-sm text-[var(--ink-mute)]">{a.artist_name}</div>}
                  <div className="flex items-center gap-2 mt-2 text-sm">
                    <span className="tag-chip">{a.year}</span>
                    <ArrowRight size={12} className="opacity-0 group-hover:opacity-100 transition-opacity" />
                  </div>
                </div>
              </Link>
            )}
          />

          <Section title="tracks" items={r.tracks} icon={Music}
            render={(t) => (
              <Link key={t.id} to={`/track/${t.id}`} className="brutal-card p-5 flex items-start gap-4 group">
                <div className="flex-1 min-w-0">
                  <div className="meta-ink">track</div>
                  <div className="font-display font-bold text-xl truncate">{t.title}</div>
                  {t.artist_name && <div className="font-editorial italic text-sm text-[var(--ink-mute)]">{t.artist_name}</div>}
                  <div className="flex items-center gap-2 mt-2 text-sm">
                    <span className="tag-chip">{t.duration}</span>
                    <ArrowRight size={12} className="opacity-0 group-hover:opacity-100 transition-opacity" />
                  </div>
                </div>
              </Link>
            )}
          />

          <Section title="artists" items={r.artists} icon={Disc3}
            render={(a) => (
              <div key={a.id} className="brutal-card-static p-5">
                <div className="meta-ink">artist</div>
                <div className="font-display font-bold text-xl mt-1">{a.name}</div>
                {a.tagline && <p className="font-editorial italic text-sm mt-1 line-clamp-2">{a.tagline}</p>}
                <Link to={`/explore?artist=${encodeURIComponent(a.name)}`} className="inline-flex items-center gap-1 text-sm underline mt-2">
                  view albums <ArrowRight size={12} />
                </Link>
              </div>
            )}
          />

          <Section title="lore" items={r.lore}
            render={(l) => (
              <Link key={l.id} to={`/lore/${l.id}`} className="brutal-card p-5">
                <div className="meta-ink">lore · {l.depth}</div>
                <div className="font-display font-bold text-xl mt-1">{l.title}</div>
                <p className="font-editorial italic text-sm mt-2 line-clamp-2">{l.excerpt}</p>
                <div className="meta-ink mt-2">by {l.author}</div>
              </Link>
            )}
          />
        </>
      )}

      {!q && (
        <div className="mt-10">
          <p className="font-editorial italic text-xl">type in the search bar above to explore the archive.</p>
          <p className="meta-ink mt-2">search across albums, tracks, artists, and lore entries.</p>
        </div>
      )}
    </div>
  );
}
